#include <iomanip>
#include <iostream>
#include <stdexcept>

void withdraw(double& balance, double amount) {
    if (amount > balance) {
        throw std::runtime_error("insufficient funds");
    }
    balance -= amount;
}

int main() {
    double balance = 0.0;
    double amount = 0.0;
