steps.body:
Your own exception type says exactly what went wrong, and a caller can catch it separately. The usual recipe derives from `std::runtime_error` and passes the message to its constructor:

```cpp
class ValidationError : public std::runtime_error {
public:
    explicit ValidationError(const std::string& msg) : std::runtime_error(msg) {}
};
std::cout << ValidationError("bad age").what() << '\n';  // bad age
```

`: public std::runtime_error` makes `ValidationError` a kind of `runtime_error`. The Inheritance lesson explains the details. For now, the recipe gives you `what()` for free, returning the message you passed in.

Throw it like any other exception: `throw ValidationError("age 200 out of range");`.

A `catch` for a base type also catches the types derived from it, so `catch (const std::exception& e)` catches a `ValidationError` too. That is why order matters: catch your own type first, then `std::exception` as the fallback for everything else.

```cpp harness
#include <bits/stdc++.h>

class ValidationError : public std::runtime_error {
public:
    explicit ValidationError(const std::string& msg) : std::runtime_error(msg) {}
};

void validateAge(int age) {
    if (age < 0 || age > 150) {
        throw ValidationError("age " + std::to_string(age) + " out of range");
    }
}

int main() {
    const std::vector<std::string> inputs = {"42", "200", "abc"};
    for (const auto& text : inputs) {
        try {
            const int age = std::stoi(text);
            validateAge(age);
            std::cout << age << " ok\n";
        {{code}}
    }
    return 0;
}
```

```cpp
} catch (const ValidationError& e) {
    std::cout << "Invalid: " << e.what() << '\n';  // your message
} catch (const std::exception&) {
    std::cout << "bad input\n";                  // library errors
}
```

Swap those two blocks and the custom handler never runs. g++ even warns that the exception will be caught by the earlier handler.

example.code:
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

class ValidationError : public std::runtime_error {
public:
    explicit ValidationError(const std::string& msg) : std::runtime_error(msg) {}
};

void validateAge(int age) {
    if (age < 0 || age > 150) {
        throw ValidationError("age " + std::to_string(age) + " out of range");
    }
}

int main() {
    const std::vector<std::string> inputs = {"42", "200", "abc"};
    for (const auto& text : inputs) {
        try {
            const int age = std::stoi(text);
            validateAge(age);
            std::cout << age << " ok\n";
        } catch (const ValidationError& e) {
            std::cout << "Invalid: " << e.what() << '\n';
        } catch (const std::exception&) {
            std::cout << text << ": bad input\n";
        }
    }
    return 0;
}

