#include <iostream>
#include <map>
#include <stdexcept>
#include <string>

class OutOfStock : public std::runtime_error {
public:
    explicit OutOfStock(const std::string& item) : std::runtime_error(item) {}
};

void order(std::map<std::string, int>& stock, const std::string& item, int qty) {
    auto it = stock.find(item);
    if (it == stock.end() || it->second < qty) {
        throw OutOfStock(item);
    }
    it->second -= qty;
}

int main() {
    std::map<std::string, int> stock = {{"apple", 5}, {"pear", 2}, {"plum", 0}};
    std::string item;
    int qty = 0;
    while (std::cin >> item >> qty) {
        try {
            order(stock, item, qty);
            std::cout << "ok " << item << '\n';
        } catch (const OutOfStock& e) {
            std::cout << "Out of stock: " << e.what() << '\n';
        } catch (const std::exception&) {
            std::cout << "Error\n";
        }
    }
    return 0;
}

steps.body:
When an exception leaves a function, C++ *unwinds the stack*: every local object in every function it passes through is destroyed, and its destructor runs, before the `catch` block starts. This is why RAII matters. A class that releases its resource in the destructor cleans up on every exit path, including a throw.

Raw `new` has no destructor to help it:

```cpp harness
#include <bits/stdc++.h>

void risky() {
    throw std::runtime_error("risky failed");
}

{{code}}

int main() {
    try {
        leaky();
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}
```

```cpp
void leaky() {
    int* data = new int[100];
    risky();          // throws
    delete[] data;    // skipped: the 400 bytes leak
}
```

Use `std::vector<int> data(100);` or a `std::unique_ptr` instead. Their destructors free the heap memory during unwinding, so nothing leaks.

`noexcept` promises that a function never throws: `int size() const noexcept`. If an exception tries to escape a `noexcept` function anyway, the program calls `std::terminate` and stops. No `catch` outside the function ever sees it.

> Gotcha: destructors are `noexcept` by default. Never throw from one: a destructor that throws ends the program, so destructors only clean up quietly.

example.code:
#include <iostream>
#include <stdexcept>
#include <string>

class Tracer {
public:
    explicit Tracer(const std::string& name) : name_(name) {
        std::cout << "open " << name_ << '\n';
    }
    ~Tracer() {
        std::cout << "close " << name_ << '\n';
    }

private:
    std::string name_;
};

void save(const std::string& file, bool diskFull) {
    Tracer tracer(file);
    if (diskFull) {
        throw std::runtime_error("disk full");
    }
    std::cout << "saved " << file << '\n';
}

int main() {
    try {
        save("notes.txt", false);
        save("photo.png", true);
        save("song.mp3", false);
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
    return 0;
}

