#include <iostream>
#include <stdexcept>
#include <string>

class Step {
public:
    explicit Step(int number) : number_(number) {
        std::cout << "open " << number_ << '\n';
    }
    ~Step() {
        std::cout << "close " << number_ << '\n';
    }

private:
    int number_;
};

void runStep(int number, int failAt) {
    Step step(number);
    if (number == failAt) {
        throw std::runtime_error("step " + std::to_string(number) + " failed");
    }
    std::cout << "done " << number << '\n';
}

int main() {
    int failAt = 0;
    std::cin >> failAt;
    try {
        for (int i = 1; i <= 3; ++i) {
            runStep(i, failAt);
        }
        std::cout << "all steps finished\n";
    } catch (const std::exception& e) {
        std::cout << "handled: " << e.what() << '\n';
    }
    return 0;
}
